import os,sys,json,hashlib,tarfile,stat
from pathlib import Path
root=Path(sys.argv[1]);manifest={};paths=[]
for directory in ('run','results'):
 for p in (root/directory).rglob('*'):
  if not p.is_file() or p.is_symlink():continue
  assert not p.name.endswith('.lock') or p.stat().st_size==0
  paths.append(p)
for p in (root/'etc').glob('*.toml'):
 if p.is_file() and not p.is_symlink():paths.append(p)
text=root/'stage/runtime-text.tar'
with tarfile.open(text,'w') as t:
 for p in paths:
  data=p.read_bytes();rel=str(p.relative_to(root));manifest[rel]={'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)};t.add(p,arcname=rel,recursive=False)
logs=root/'stage/full-logs.tar'
with tarfile.open(logs,'w') as t:
 t.add(root/'logs',arcname='logs')
state=root/'stage/durable-metadata.tar'
with tarfile.open(state,'w') as t:
 if (root/'state/meta/meta-store').is_dir():t.add(root/'state/meta/meta-store',arcname='meta-store')
 for p in (root/'state/node/dfs').glob('*catalog*'):
  if p.is_file():t.add(p,arcname='dfs/'+p.name)
artifacts={}
for p in (text,logs,state):
 data=p.read_bytes();artifacts[p.name]={'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data),'guest_path':str(p)};os.chown(p,int(os.environ['SUDO_UID']),int(os.environ['SUDO_GID']));p.chmod(0o600)
print(json.dumps({'status':'EXPORTED_NO_CHUNK_DATA','text_members':manifest,'artifacts':artifacts},indent=2))

